def build():
    out = dict(MISC)
    for npc, d in NPC.items():
        for k, v in d.items():
            out[f"valdren.npc.{npc}.{k}"] = v
    for q, d in QUESTS.items():
        for k, v in d.items():
            out[f"valdren.quest.{q}.{k}"] = v
    for i, page in enumerate(GUIDE):
        out[f"valdren.guide.page.{i}"] = page
    return out
